import{_ as n,C as a,o as r,c as o,E as i,a4 as s}from"./chunks/framework.BMj-uaUw.js";const b=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[{"level":2,"title":"从上一单元留下的问题说起","slug":"从上一单元留下的问题说起","link":"#从上一单元留下的问题说起","children":[]},{"level":2,"title":"本单元的知识地图","slug":"本单元的知识地图","link":"#本单元的知识地图","children":[]},{"level":2,"title":"这次课的 4 学时怎么用","slug":"这次课的-4-学时怎么用","link":"#这次课的-4-学时怎么用","children":[]},{"level":2,"title":"与单元 9 的衔接：第 10 周的阶段性任务","slug":"与单元-9-的衔接-第-10-周的阶段性任务","link":"#与单元-9-的衔接-第-10-周的阶段性任务","children":[]},{"level":2,"title":"开始之前","slug":"开始之前","link":"#开始之前","children":[]},{"level":2,"title":"这个单元的产出","slug":"这个单元的产出","link":"#这个单元的产出","children":[]},{"level":2,"title":"读完之后","slug":"读完之后","link":"#读完之后","children":[]}],"relativePath":"unit10/index.md","filePath":"unit10/index.md","lastUpdated":1789356894000}'),d={name:"unit10/index.md"};function l(c,t,h,p,g,u){const e=a("UnitMeta");return r(),o("div",null,[i(e,{unit:"单元 10",title:"Pinia 状态管理与数据请求层",module:"模块四 · 应用架构",hours:"4 学时",week:"第 10 周",goals:["能判断哪些状态该放到全局、哪些应该留在组件里","能写出可维护的状态模块，并让它在刷新后仍然保留","能封装统一的数据请求层，集中处理凭证注入与错误"],outcomes:["登录态状态模块","请求层封装"]}),t[0]||(t[0]=s(`<h2 id="从上一单元留下的问题说起" tabindex="-1">从上一单元留下的问题说起 <a class="header-anchor" href="#从上一单元留下的问题说起" aria-label="Permalink to &quot;从上一单元留下的问题说起&quot;">​</a></h2><p><a href="/frontend-engineering-course/unit09/">单元 9</a> 结束时，你已经做完了登录鉴权：路由能拦人，没登录会被挡到登录页， 登录成功后能回到原来想去的地址。但如果你真的动手写过，会发现有几个地方很别扭：</p><ul><li>登录成功后拿到的 token，你存在哪里？存在 <code>localStorage</code> 里，然后组件里到处 <code>localStorage.getItem(&#39;token&#39;)</code>？</li><li>顶部导航栏要显示当前用户名，这个数据从哪来？是登录页把它通过 props 一路传下去的？</li><li>用户点了退出，除了清掉 token，还有什么要一起清？好几个页面里缓存的用户信息怎么办？</li><li>活动列表页要调接口，每个页面都写一遍 <code>axios.get(...)</code>，地址、超时、错误提示各写各的？</li></ul><p>这四个问题，前三个属于<strong>全局状态该放在哪</strong>，第四个属于<strong>请求该怎么发</strong>。 它们正是这个单元要解决的两件事。</p><div class="tip custom-block"><p class="custom-block-title">一个单元解决一类问题</p><ul><li><strong>全局状态</strong>：多个不相邻的页面都要用的数据（登录用户、权限、全局提示）交给 Pinia。</li><li><strong>数据请求</strong>：所有接口调用统一走一个封装好的请求层，组件里只调用函数、不碰地址。</li></ul></div><h2 id="本单元的知识地图" tabindex="-1">本单元的知识地图 <a class="header-anchor" href="#本单元的知识地图" aria-label="Permalink to &quot;本单元的知识地图&quot;">​</a></h2><table tabindex="0"><thead><tr><th>小节</th><th>讲什么</th><th>解决什么问题</th></tr></thead><tbody><tr><td><a href="/frontend-engineering-course/unit10/01-when-global.html">10.1 什么时候需要全局状态</a></td><td>props、provide/inject、全局状态三种方案的适用场景</td><td>数据该放哪一层</td></tr><tr><td><a href="/frontend-engineering-course/unit10/02-pinia-basics.html">10.2 Pinia 两种写法</a></td><td>选项式与组合式写法、<code>storeToRefs</code>、跨模块调用</td><td>状态模块怎么写才可维护</td></tr><tr><td><a href="/frontend-engineering-course/unit10/03-persist.html">10.3 状态持久化</a></td><td>手写持久化与 <code>pinia-plugin-persistedstate</code>、安全边界</td><td>刷新后登录态为什么不丢</td></tr><tr><td><a href="/frontend-engineering-course/unit10/04-request-layer.html">10.4 请求层封装</a></td><td>axios 实例、双拦截器、接口按业务拆分</td><td>组件里不再出现接口地址</td></tr><tr><td><a href="/frontend-engineering-course/unit10/05-error-handling.html">10.5 错误分层处理</a></td><td>网络、HTTP、业务、权限四层错误各自怎么处理</td><td>出错时用户看到什么</td></tr><tr><td><a href="/frontend-engineering-course/unit10/06-case-fetch.html">案例 04 · 从接口获取数据</a></td><td>四态模板、<code>useRequest</code>、请求竞态、加载更多</td><td>把上面几节拼成一个真实页面</td></tr><tr><td><a href="/frontend-engineering-course/unit10/ai-collaboration.html">AI 协作 · 接口约定最容易走偏</a></td><td>成功码是 0 不是 200、错误对象要带上业务码、字段名转换</td><td>让约定落到代码里，不靠记</td></tr><tr><td><a href="/frontend-engineering-course/unit10/practice.html">课后练习</a></td><td>状态模块 + 请求层 + 列表页接真接口</td><td>把知识变成能跑的项目代码</td></tr></tbody></table><p>六节之间是一条线：先决定<strong>放哪</strong>（10.1），再学<strong>怎么写</strong>（10.2）， 解决<strong>刷新丢失</strong>（10.3），然后把<strong>数据来源</strong>统一起来（10.4）， 再想清楚<strong>出错怎么办</strong>（10.5），最后<strong>拼成一个完整页面</strong>（案例 04）。</p><h2 id="这次课的-4-学时怎么用" tabindex="-1">这次课的 4 学时怎么用 <a class="header-anchor" href="#这次课的-4-学时怎么用" aria-label="Permalink to &quot;这次课的 4 学时怎么用&quot;">​</a></h2><table tabindex="0"><thead><tr><th>环节</th><th>时长</th><th>做什么</th></tr></thead><tbody><tr><td>检查预习</td><td>0.3 学时</td><td>抽问：上单元登录后的 token 你存在哪？退出时清干净了吗？</td></tr><tr><td>讲解</td><td>1.4 学时</td><td>重点讲 10.2 的两种写法与 10.4 的请求层；10.1、10.3、10.5 用课堂讨论带过</td></tr><tr><td>现场任务</td><td>1.7 学时</td><td>写出登录态与活动列表两个状态模块；封装请求层并接上一个 mock 接口</td></tr><tr><td>复盘</td><td>0.6 学时</td><td>展示两份请求层实现，对比拦截器里各自处理了哪些错误</td></tr></tbody></table><h2 id="与单元-9-的衔接-第-10-周的阶段性任务" tabindex="-1">与单元 9 的衔接：第 10 周的阶段性任务 <a class="header-anchor" href="#与单元-9-的衔接-第-10-周的阶段性任务" aria-label="Permalink to &quot;与单元 9 的衔接：第 10 周的阶段性任务&quot;">​</a></h2><p>这个单元不是孤立的。<strong>本单元与单元 9 一起，构成第 10 周的阶段性任务</strong> —— 把路由与状态接起来，跑通一条完整的鉴权链路：</p><ol><li><strong>未登录被拦</strong>：用户直接访问 <code>/activities</code>，路由守卫发现没有登录凭证，跳转到登录页， 并把原本要去的地址记下来。</li><li><strong>登录后回原地址</strong>：用户登录成功，状态模块写入 token 与用户信息， 路由跳回当初记下的 <code>/activities</code>，这次守卫放行。</li><li><strong>退出后再次被拦</strong>：用户点退出，状态模块清空登录信息并清掉持久化数据， 再访问 <code>/activities</code> 时又被拦回登录页。</li></ol><p>这条链路的每一环都同时用到路由和状态：<strong>路由负责&quot;能不能进&quot;，状态负责&quot;记不记得我是谁&quot;</strong>。 少任何一半都跑不通。做完这个单元，第 10 周的任务才算完成。</p><div class="warning custom-block"><p class="custom-block-title">这次课最容易出问题的三个地方</p><ol><li><strong>在模块顶层调用 <code>useAuthStore()</code></strong> —— 会报 &quot;getActivePinia() was called but there was no active Pinia&quot;。 必须在函数内部调用，原因见 <a href="/frontend-engineering-course/unit10/02-pinia-basics.html#跨模块调用怎么写">10.2</a>。</li><li><strong>拦截器里直接 <code>window.location.href = &#39;/login&#39;</code></strong> —— 会整页刷新，丢掉当前路由和已填表单。 正确做法是用 router 实例跳转，见 <a href="/frontend-engineering-course/unit10/04-request-layer.html#401-怎么处理">10.4</a>。</li><li><strong>把整个 store 都持久化</strong> —— 把加载态、错误信息也写进 <code>localStorage</code>， 刷新后页面带着一个永远转不完的圈。见 <a href="/frontend-engineering-course/unit10/03-persist.html">10.3</a>。</li></ol></div><h2 id="开始之前" tabindex="-1">开始之前 <a class="header-anchor" href="#开始之前" aria-label="Permalink to &quot;开始之前&quot;">​</a></h2><p>这个单元需要你手上已经有一个能跑起来的项目，至少包含：</p><ul><li>Vue 3 + Vue Router + Pinia 的基础骨架（用 <code>create-vue</code> 勾上 Router 和 Pinia 就有）。</li><li>一个能发起请求的后端接口。<strong>没有后端也没关系</strong> —— 本单元用一个本地 mock 服务， 做法见 <a href="/frontend-engineering-course/unit10/06-case-fetch.html#准备一个能用的接口">案例 04</a>。</li><li>已经配好 <code>@</code> 别名指向 <code>src</code>（在 <a href="/frontend-engineering-course/unit02/04-vite.html">单元 2</a> 配过）。</li></ul><h2 id="这个单元的产出" tabindex="-1">这个单元的产出 <a class="header-anchor" href="#这个单元的产出" aria-label="Permalink to &quot;这个单元的产出&quot;">​</a></h2><p>按课程要求，这次课交两样东西：</p><p><strong>一、登录态状态模块</strong></p><table tabindex="0"><thead><tr><th>项目</th><th>要求</th></tr></thead><tbody><tr><td>状态字段</td><td>token、用户基本信息（用户名、角色）、加载态、错误信息</td></tr><tr><td>动作</td><td>登录、退出、恢复登录态（从持久化读取）、刷新用户信息</td></tr><tr><td>持久化</td><td><strong>只持久化 token 与用户基本信息</strong>，不持久化加载态与错误信息</td></tr><tr><td>与路由的关系</td><td>路由守卫从状态模块读登录判断，不再直接读 <code>localStorage</code></td></tr></tbody></table><p><strong>二、请求层封装</strong></p><table tabindex="0"><thead><tr><th>项目</th><th>要求</th></tr></thead><tbody><tr><td>实例</td><td>统一的基础地址与超时，基础地址从环境变量读</td></tr><tr><td>请求拦截器</td><td>从状态模块取 token 注入请求头</td></tr><tr><td>响应拦截器</td><td>业务状态码判定、<code>401</code> 跳登录、其他错误统一提示</td></tr><tr><td>接口文件</td><td>按业务模块拆分，<code>src/api/activity.js</code>、<code>src/api/signup.js</code> 各自独立</td></tr><tr><td>组件</td><td><strong>组件里不出现任何接口地址</strong>，只调用 <code>api/</code> 导出的函数</td></tr></tbody></table><details class="details custom-block"><summary>一份合格的请求层目录长什么样</summary><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>src/</span></span>
<span class="line"><span>├── api/</span></span>
<span class="line"><span>│   ├── request.js         axios 实例与拦截器</span></span>
<span class="line"><span>│   ├── activity.js        活动相关接口</span></span>
<span class="line"><span>│   ├── signup.js          报名审核相关接口</span></span>
<span class="line"><span>│   └── auth.js            登录相关接口</span></span>
<span class="line"><span>├── stores/</span></span>
<span class="line"><span>│   ├── auth.js            登录态模块</span></span>
<span class="line"><span>│   └── activity.js        活动列表状态模块</span></span>
<span class="line"><span>└── views/</span></span>
<span class="line"><span>    └── ActivityListView.vue   组件里只 import 函数，不写地址</span></span></code></pre></div><p>判断标准：把 <code>src/api/</code> 里的地址全部改一遍，<code>views/</code> 里一个字都不用动。</p></details><h2 id="读完之后" tabindex="-1">读完之后 <a class="header-anchor" href="#读完之后" aria-label="Permalink to &quot;读完之后&quot;">​</a></h2><p>先读 <a href="/frontend-engineering-course/unit10/01-when-global.html">10.1</a>，它会帮你建立一个判断标准 —— <strong>不是所有数据都该塞进全局状态</strong>。想清楚这一点，后面写模块时才不会把 Pinia 用成一个巨大的垃圾抽屉。</p><hr><p>上一单元：<a href="/frontend-engineering-course/unit09/">单元 9 · 路由与登录鉴权</a> · 下一节：<a href="/frontend-engineering-course/unit10/01-when-global.html">10.1 什么时候需要全局状态</a></p>`,29))])}const m=n(d,[["render",l]]);export{b as __pageData,m as default};
